import type { Plugin } from "vite";

/**
 * The site's security headers, in one place. Everything that serves the production build reads them here:
 *  - `vercel.json` (generated by `pnpm schemas`, which runs before every build; a unit test fails when it's stale),
 *  - `vite preview` (the `securityHeaders()` plugin below), so the e2e suite runs under the real policy.
 * The dev server sends none of them: React Refresh's preamble is an inline script, and HMR evaluates
 * modules in ways a strict script-src forbids. Test the policy against a build (E2E_TARGET=build).
 *
 * Why each source is allowed (see also docs/INTEROP.md, "Security headers"):
 *  - script-src: the app's own bundles, plus Google's two loaders, fetched only when Google Drive is
 *    configured and the File menu opens (src/interop/gdrive/google.ts). No 'unsafe-inline' and no
 *    'unsafe-eval': the static pages' scripts are files too (public/theme.js, auth.js, skill/copy.js).
 *  - style-src 'unsafe-inline': the static pages (privacy, sign-in, skill) carry a <style> block, and the
 *    Google Picker and Identity Services add styles to the page. React's `style` props don't need it (they
 *    go through the CSSOM, which CSP doesn't restrict). Inline styles can't run code; scripts stay strict.
 *  - connect-src: exactly the endpoints the storage providers call (src/interop/storage, src/interop/gdrive).
 *    OneDrive's file downloads come from pre-authenticated URLs on Microsoft's content hosts, hence the
 *    wildcards: *.1drv.com and *.microsoftpersonalcontent.com (personal), *.sharepoint.com (work or school).
 *  - frame-src: the embed dialog's preview (this site), the Google Picker and Identity Services frames.
 *  - frame-ancestors: embeds (`?embed=1`, including the host-supplied `?embed=1&host=1`) may be framed by any
 *    site; the app itself only by this site. The host-supplied embed keeps connect-src as it is: the page that
 *    embeds it fetches the diagram and hands it over with postMessage, the frame never fetches it.
 *  - worker-src 'self': the live view's particle worker is a bundled file, never a blob.
 *  - img-src / media-src data: and blob:: exported images, thumbnails and recorded videos are made in the page.
 */

const GOOGLE = {
  script: ["https://accounts.google.com/gsi/client", "https://apis.google.com"],
  style: ["https://accounts.google.com/gsi/style"],
  connect: [
    "https://accounts.google.com/gsi/",
    // Drive REST v3 and uploads (src/interop/gdrive/client.ts).
    "https://www.googleapis.com",
    // Identity Services' token revocation (Sign out of Google Drive).
    "https://oauth2.googleapis.com",
  ],
  frame: ["https://accounts.google.com/gsi/", "https://docs.google.com", "https://drive.google.com"],
};

const MICROSOFT = {
  connect: [
    // Token endpoint (auth code + PKCE, refresh) and Graph (src/interop/storage/onedrive.ts).
    "https://login.microsoftonline.com",
    "https://graph.microsoft.com",
    // @microsoft.graph.downloadUrl hosts.
    "https://*.1drv.com",
    "https://*.microsoftpersonalcontent.com",
    "https://*.sharepoint.com",
  ],
};

const DROPBOX = {
  // Token endpoint and RPC (api), uploads and downloads (content) (src/interop/storage/dropbox.ts).
  connect: ["https://api.dropboxapi.com", "https://content.dropboxapi.com"],
};

/** Every origin a storage provider's code calls with fetch (the unit test checks the providers' source). */
export const PROVIDER_CONNECT = [...GOOGLE.connect, ...MICROSOFT.connect, ...DROPBOX.connect];

export function cspDirectives({ embed }: { embed: boolean }): [string, string[]][] {
  // An embed (a link's, an example's or one its host page supplies) never saves, opens or signs in anywhere: it
  // talks to this site only, so no storage provider's script, frame or endpoint is allowed in it.
  const providers = <T>(list: readonly T[]): T[] => (embed ? [] : [...list]);
  return [
    ["default-src", ["'self'"]],
    ["script-src", ["'self'", ...providers(GOOGLE.script)]],
    ["style-src", ["'self'", "'unsafe-inline'", ...providers(GOOGLE.style)]],
    ["img-src", ["'self'", "data:", "blob:"]],
    ["font-src", ["'self'", "data:"]],
    ["connect-src", ["'self'", ...providers(PROVIDER_CONNECT)]],
    ["media-src", ["'self'", "blob:"]],
    ["worker-src", ["'self'"]],
    ["frame-src", ["'self'", ...providers(GOOGLE.frame)]],
    ["frame-ancestors", [embed ? "*" : "'self'"]],
    ["form-action", ["'self'"]],
    ["base-uri", ["'self'"]],
    ["object-src", ["'none'"]],
  ];
}

export const contentSecurityPolicy = (o: { embed: boolean }) =>
  cspDirectives(o)
    .map(([name, values]) => `${name} ${values.join(" ")}`)
    .join("; ");

/**
 * Features the app never uses are off for it and anything it frames. The microphone is for dictation
 * (the AI panel's Dictate), display capture for Record video. The camera is left at the browser's default
 * (this site only) rather than off: Chromium checks it on every getDisplayMedia call and logs a policy
 * violation when it's denied, though the app never asks for a camera.
 *
 * Only features every current Chromium build recognises on every desktop platform: an unknown name makes
 * the browser log "Unrecognized feature" for every page (Linux Chromium has no `bluetooth`, for example).
 * tests/e2e/csp.spec.ts checks each one against `document.featurePolicy.features()`.
 */
export const PERMISSIONS_FEATURES: [feature: string, allow: "self" | "none"][] = [
  ["microphone", "self"],
  ["display-capture", "self"],
  ["geolocation", "none"],
  ["payment", "none"],
  ["usb", "none"],
  ["serial", "none"],
];

export const PERMISSIONS_POLICY = PERMISSIONS_FEATURES.map(
  ([f, allow]) => `${f}=${allow === "self" ? "(self)" : "()"}`,
).join(", ");

/** Sent with every response. */
export const COMMON_HEADERS: Record<string, string> = {
  // Cross-origin requests (Google, Microsoft, Dropbox) learn only the origin, never the path or query; the
  // fragment (a share link's diagram) is never sent at all. Not no-referrer: a Google API key restricted to
  // this site's referrer (the Picker's) needs the origin.
  "Referrer-Policy": "strict-origin-when-cross-origin",
  "X-Content-Type-Options": "nosniff",
  "Permissions-Policy": PERMISSIONS_POLICY,
};

/**
 * Keeps other sites' windows from holding a handle to the app, while the app's own sign-in pop-ups
 * (Google's, and auth.html for OneDrive and Dropbox) keep theirs. Not sent with auth.html, so arriving
 * there from the provider's page doesn't cut the pop-up off from the app (the BroadcastChannel fallback
 * in src/interop/storage/oauth.ts would still cope).
 */
export const OPENER_POLICY = "same-origin-allow-popups";

/**
 * An embed is any URL with an `embed` parameter (src/App.tsx uses the same rule). Matching the key alone
 * keeps Vercel's rule exact: its `has` values are regex-like, and a loose match on "1" must never hand the
 * full app `frame-ancestors *`.
 */
const isEmbed = (search: string) => new URLSearchParams(search).has("embed");
const isAuthPage = (pathname: string) => /\/auth\.html$/.test(pathname);

/**
 * The `<live-diagram>` web component (public/embed/live-diagram.js) is loaded by other sites' pages as a module
 * script, which browsers fetch with CORS: it must say any origin may read it, and that it may be embedded
 * cross-origin. Its URL isn't versioned, so it's cached for an hour (then revalidated in the background) rather
 * than for good: a fix reaches every page within the hour. It runs under the host page's own CSP, not ours.
 */
export const EMBED_SCRIPT_HEADERS: Record<string, string> = {
  "Access-Control-Allow-Origin": "*",
  "Cross-Origin-Resource-Policy": "cross-origin",
  "Cache-Control": "public, max-age=3600, stale-while-revalidate=86400",
};
const isEmbedScript = (pathname: string) => /\/embed\/[^/]+\.js$/.test(pathname);

/** The headers for one request, the same as the Vercel rules below produce. */
export function securityHeadersFor(url: string): Record<string, string> {
  const u = new URL(url, "http://localhost");
  return {
    ...COMMON_HEADERS,
    "Content-Security-Policy": contentSecurityPolicy({ embed: isEmbed(u.search) }),
    ...(isAuthPage(u.pathname) ? {} : { "Cross-Origin-Opener-Policy": OPENER_POLICY }),
    ...(isEmbedScript(u.pathname) ? EMBED_SCRIPT_HEADERS : {}),
  };
}

const EMBED_QUERY = [{ type: "query", key: "embed" }];
const pairs = (h: Record<string, string>) => Object.entries(h).map(([key, value]) => ({ key, value }));

/**
 * Only master deploys. Pull requests are tested by CI, not by preview deployments, and preview builds for
 * every branch push used up the plan's daily deployment limit. A branch deploys if any matching rule is
 * true; `**` (not `*`) also matches branch names with slashes, like `feat/x`.
 */
export const DEPLOY_BRANCHES = { "**": false, master: true };

/** vercel.json. Vercel routes on query parameters (`has` / `missing`), so embeds get their own CSP. */
export function vercelConfig() {
  return {
    $schema: "https://openapi.vercel.sh/vercel.json",
    git: { deploymentEnabled: DEPLOY_BRANCHES },
    headers: [
      { source: "/(.*)", headers: pairs(COMMON_HEADERS) },
      {
        source: "/(.*)",
        missing: EMBED_QUERY,
        headers: pairs({ "Content-Security-Policy": contentSecurityPolicy({ embed: false }) }),
      },
      {
        source: "/(.*)",
        has: EMBED_QUERY,
        headers: pairs({ "Content-Security-Policy": contentSecurityPolicy({ embed: true }) }),
      },
      { source: "/((?!auth\\.html).*)", headers: pairs({ "Cross-Origin-Opener-Policy": OPENER_POLICY }) },
      { source: "/embed/([^/]+\\.js)", headers: pairs(EMBED_SCRIPT_HEADERS) },
    ],
  };
}

export const vercelJson = () => `${JSON.stringify(vercelConfig(), null, 2)}\n`;

/** Sends the headers from `vite preview` (not the dev server; see the top of this file). */
export function securityHeaders(): Plugin {
  return {
    name: "security-headers",
    configurePreviewServer(server) {
      server.middlewares.use((req, res, next) => {
        for (const [k, v] of Object.entries(securityHeadersFor(req.originalUrl ?? req.url ?? "/"))) res.setHeader(k, v);
        next();
      });
    },
  };
}
